begin;
create extension if not exists pgtap with schema extensions;
select plan(12);
-- __RECOVERY_MIGRATION__
insert into public.parties(id,name)values('66200000-0000-4000-8000-000000000001','Ticket06 recovery rollback');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('66200000-0000-4000-8000-000000000011','ticket06-recovery@verification.test','{}','{}');
insert into public.party_members(party_id,user_id,role)values('66200000-0000-4000-8000-000000000001','66200000-0000-4000-8000-000000000011','dungeon-master');
insert into public.party_map_generation_settings(party_id,fixture_enabled,live_enabled,quota,spend_cents,reservation_cents)values('66200000-0000-4000-8000-000000000001',true,true,10,100,10);
create function pg_temp.intent(suffix text)returns jsonb language sql as $$select jsonb_build_object('requestId','66200000-0000-4000-8000-000000000'||suffix,'familyId','66200000-0000-4000-8000-000000000003','expectedVersion',0,'kind','generate','title','Recovery fixture','instructions','Sea cave','document','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}'::jsonb);$$;
set local "request.jwt.claim.role"='service_role';
select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('002'),'live');
select public.transition_map_generation('66200000-0000-4000-8000-000000000002',1,'running','{"submissionToken":"66200000-0000-4000-8000-000000000020"}');
select public.transition_map_generation('66200000-0000-4000-8000-000000000002',2,'awaiting-client-output','{"candidate":{"objectId":"66200000-0000-4000-8000-000000000002","size":68,"digest":"fixture"}}');
select ok((select provider_finished_at is not null and provider_finished_at<=deadline from public.party_map_generation_jobs where id='66200000-0000-4000-8000-000000000002'),'receipt marker is authoritatively assigned on timely transition');
select public.transition_map_generation('66200000-0000-4000-8000-000000000002',3,'cancelled','{}');
select lives_ok($$select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('004'),'live')$$,'known finished cancelled receipt permits explicit newUUID reservation');
select is(public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('002'),'live')->>'state','cancelled','sameUUID remains cancelled rather than resubmitting');
select throws_ok($$select public.complete_map_generation('66200000-0000-4000-8000-000000000002',4,'{}','{}','{}')$$,'P0001','Job/proof/object binding rejected','cancelled receipt cannot attach');
select is((select sum(reserved_cents)from public.party_map_generation_jobs where party_id='66200000-0000-4000-8000-000000000001'),20::bigint,'known cancellation never refunds cumulative spending');
select public.transition_map_generation('66200000-0000-4000-8000-000000000004',1,'running','{"submissionToken":"66200000-0000-4000-8000-000000000021"}');
select public.transition_map_generation('66200000-0000-4000-8000-000000000004',2,'cancelled','{"provider_finished_at":"2020-01-01"}');
select ok((select provider_finished_at is null from public.party_map_generation_jobs where id='66200000-0000-4000-8000-000000000004'),'caller patch cannot invent definitive receipt marker');
select throws_ok($$select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('005'),'live')$$,'P0001','Generation already active','unknown running cancellation retains original deadline hold');
update public.party_map_generation_jobs set deadline=now()-interval '1 second' where id='66200000-0000-4000-8000-000000000004';
select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('005'),'live');
select public.transition_map_generation('66200000-0000-4000-8000-000000000005',1,'running','{"submissionToken":"66200000-0000-4000-8000-000000000022"}');
select public.transition_map_generation('66200000-0000-4000-8000-000000000005',2,'uncertain','{}');
select public.transition_map_generation('66200000-0000-4000-8000-000000000005',3,'cancelled','{}');
select throws_ok($$select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('006'),'live')$$,'P0001','Generation already active','unknown uncertain cancellation also retains deadline hold');
update public.party_map_generation_jobs set deadline=now()-interval '1 second' where id='66200000-0000-4000-8000-000000000005';
update public.party_map_generation_settings set quota=3 where party_id='66200000-0000-4000-8000-000000000001';
select throws_ok($$select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('006'),'live')$$,'P0001','Generation limit reached','cancelled reservations remain counted toward quota');
update public.party_map_generation_settings set quota=10,spend_cents=30 where party_id='66200000-0000-4000-8000-000000000001';
select throws_ok($$select public.reserve_map_generation('66200000-0000-4000-8000-000000000011',pg_temp.intent('006'),'live')$$,'P0001','Generation limit reached','cancelled reservations remain counted toward spending');
select is((select count(*)from public.party_map_artwork_versions where party_id='66200000-0000-4000-8000-000000000001'),0::bigint,'cancel/retry reservation never attaches versions');
select is((select count(*)from public.party_map_presentations where party_id='66200000-0000-4000-8000-000000000001'),0::bigint,'cancel/retry never implicitly selects presentation');
select * from finish();
rollback;
